// Weather Widget SaaS Platform - Backend
const express = require('express');
const cors = require('cors');
const axios = require('axios');
require('dotenv').config();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const { Pool } = require('pg');

const app = express();
app.use(cors());
app.use(express.json());

// Database setup
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://localhost/weatherwidget'
});

// Initialize database
createTable = async () => {
  try {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS users (
        id SERIAL PRIMARY KEY,
        email VARCHAR(255) UNIQUE,
        stripe_customer_id VARCHAR(255),
        subscription_status VARCHAR(50) DEFAULT 'free',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS widgets (
        id SERIAL PRIMARY KEY,
        user_id INTEGER REFERENCES users(id),
        widget_key VARCHAR(255) UNIQUE,
        location VARCHAR(255),
        settings JSONB,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );
    `);
    console.log('✅ Database initialized');
  } catch (err) {
    console.error('Database setup error:', err);
  }
};
createTable();

// Weather API integration
const getWeatherData = async (location) => {
  try {
    const apiKey = process.env.OPENWEATHER_API_KEY || 'demo';
    const response = await axios.get(
      `https://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${apiKey}&units=metric`
    );
    return response.data;
  } catch (error) {
    return {
      main: { temp: 22, humidity: 65 },
      weather: [{ main: 'Clear', description: 'Sunny' }],
      wind: { speed: 5.2 },
      name: location
    };
  }
};

// Stripe payment integration
app.post('/api/create-checkout-session', async (req, res) => {
  try {
    const { email } = req.body;

    // Create Stripe customer
    const customer = await stripe.customers.create({ email });

    const session = await stripe.checkout.sessions.create({
      customer: customer.id,
      payment_method_types: ['card'],
      line_items: [{
        price: process.env.STRIPE_PRICE_ID,
        quantity: 1,
      }],
      mode: 'subscription',
      success_url: 'https://weatherwidget.com/success',
      cancel_url: 'https://weatherwidget.com',
    });

    res.json({ sessionId: session.id, customerId: customer.id });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Widget creation endpoint
app.post('/api/widget', async (req, res) => {
  try {
    const { email, location, settings } = req.body;
    const widgetKey = Math.random().toString(36).substring(2, 15);

    // Create user if doesn't exist
    let userResult = await pool.query('SELECT id FROM users WHERE email = $1', [email]);
    let userId;

    if (userResult.rows.length === 0) {
      userResult = await pool.query(
        'INSERT INTO users (email) VALUES ($1) RETURNING id', 
        [email]
      );
    }
    userId = userResult.rows[0].id;

    // Create widget
    await pool.query(
      'INSERT INTO widgets (user_id, widget_key, location, settings) VALUES ($1, $2, $3, $4)',
      [userId, widgetKey, location, JSON.stringify(settings)]
    );

    res.json({ success: true, widgetKey });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Widget data endpoint
app.get('/api/widget/:key', async (req, res) => {
  try {
    const { key } = req.params;
    const result = await pool.query('SELECT * FROM widgets WHERE widget_key = $1', [key]);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Widget not found' });
    }

    const widget = result.rows[0];
    const weather = await getWeatherData(widget.location);

    res.json({ weather, settings: widget.settings });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Admin dashboard endpoint
app.get('/api/admin/stats', async (req, res) => {
  try {
    const users = await pool.query('SELECT COUNT(*) FROM users');
    const widgets = await pool.query('SELECT COUNT(*) FROM widgets');
    const paid = await pool.query("SELECT COUNT(*) FROM users WHERE subscription_status = 'active'");

    res.json({
      totalUsers: users.rows[0].count,
      totalWidgets: widgets.rows[0].count,
      payingUsers: paid.rows[0].count
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
  console.log(`🚀 Weather Widget SaaS running on port ${PORT}`);
});
EOF

